
create table public.courses (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  title jsonb not null,
  order_index int not null,
  published boolean not null default false,
  created_at timestamptz not null default now()
);

create table public.units (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.courses(id) on delete cascade,
  title jsonb not null,
  order_index int not null
);

create table public.lessons (
  id uuid primary key default gen_random_uuid(),
  unit_id uuid not null references public.units(id) on delete cascade,
  title jsonb not null,
  body jsonb not null,
  order_index int not null
);

create table public.assessment_questions (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('quick_check','unit_exam','final_exam')),
  lesson_id uuid references public.lessons(id) on delete cascade,
  unit_id uuid references public.units(id) on delete cascade,
  course_id uuid references public.courses(id) on delete cascade,
  prompt jsonb not null,
  choices jsonb not null,
  correct_choice_id text not null,
  hint jsonb,
  order_index int not null,
  check (
    (kind = 'quick_check' and lesson_id is not null and unit_id is null and course_id is null) or
    (kind = 'unit_exam'   and unit_id   is not null and lesson_id is null and course_id is null) or
    (kind = 'final_exam'  and course_id is not null and lesson_id is null and unit_id is null)
  )
);

alter table public.courses enable row level security;
alter table public.units enable row level security;
alter table public.lessons enable row level security;
alter table public.assessment_questions enable row level security;

create policy "Published courses are publicly readable"
  on public.courses for select
  using (published = true);

create policy "Units of published courses are publicly readable"
  on public.units for select
  using (exists (select 1 from public.courses c where c.id = course_id and c.published = true));

create policy "Lessons of published courses are publicly readable"
  on public.lessons for select
  using (exists (
    select 1 from public.units u join public.courses c on c.id = u.course_id
    where u.id = unit_id and c.published = true
  ));

create policy "Questions of published courses are publicly readable"
  on public.assessment_questions for select
  using (
    (lesson_id is not null and exists (
      select 1 from public.lessons l join public.units u on u.id = l.unit_id
      join public.courses c on c.id = u.course_id
      where l.id = lesson_id and c.published = true
    )) or
    (unit_id is not null and exists (
      select 1 from public.units u join public.courses c on c.id = u.course_id
      where u.id = unit_id and c.published = true
    )) or
    (course_id is not null and exists (
      select 1 from public.courses c where c.id = course_id and c.published = true
    ))
  );

revoke insert, update, delete on public.courses, public.units, public.lessons, public.assessment_questions
  from anon, authenticated;






