  ('beb9fe14-553e-48c5-9ea0-dd8c0faac639', '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Toward Mastery"}', 3);
insert into public.lessons (id, unit_id, title, body, order_index) values
  ('3e536c0f-0d9a-44d8-9058-22558a674248', '4f017236-e9f5-4b94-b6ea-148d2efc7df0', '{"en": "Your Digital Identity & Privacy"}', '{"en": "Let''s start with what''s actually at stake: how much of yourself is visible online, and who''s piecing it together. That picture is built from two places — the quiet data trail you leave everywhere, and the things you deliberately share on social media.\n\n## Who Are You, Online?\n\nEvery account you create, every photo you upload, every comment you leave, every like you drop — all of it piles up into something called your **digital identity**. Here''s the part most people miss: it''s not just the stuff you consciously post. It''s the site you logged in from, the device you''re using, even the time of day you''re usually online. All of it gets collected, whether you''re paying attention or not.\n\n\n\n![What makes up your digital identity](course-media:u1-l1-01-digital-identity-inputs.png)\n\nWhy does this matter? Because anyone — a recruiter checking you out before an interview, or, less pleasantly, an attacker with bad intentions — can piece all of this together into a full picture of you without you ever noticing. Picture this: someone sees from your photos exactly when you travel, and from your posts exactly where you live. Now they know when your house is empty. That''s not paranoia — that''s just how this works.\n\n**How do you protect your digital identity?**\n- Review your privacy settings regularly — don''t just set them once and forget them\n- Think before you post anything revealing your location or your daily routine\n- Don''t reuse the same username and personal details everywhere — if one account gets breached, you don''t want your whole life exposed with it\n\n## Your Privacy on Social Media\n\nSocial media is one of the biggest everyday sources of that digital identity we just described. Used carelessly, these same platforms can become the easiest door into your personal life.\n\n**What should you never post?**\n- Your exact live location while you''re broadcasting from it\n- Details of your daily routine — when you leave, when your house is empty\n- Detailed information about your kids or family\n- Photos containing sensitive documents like your passport or ID\n\n**Why does this actually matter?** Because people monitor public accounts specifically to figure out who''s about to travel, whose house sits empty, or to pull off **impersonation** — creating a fake account under your name to scam your friends and family.\n\n\n\n![How one post spreads beyond your control](course-media:u1-l1-02-content-spread.png)\n\nMy advice: review your privacy settings regularly, keep track of who can actually see your posts, and don''t accept friend requests from accounts you don''t recognize.\n\n## Key Takeaways\n- Your digital identity is built from more than what you post — logins, devices, and location data all add up.\n- Don''t reuse the same username and personal details everywhere.\n- Reviewing your privacy settings regularly is one of the simplest, highest-value habits you can build."}', 1),
  ('556c8347-176c-4941-88e9-a73d04f5f6a6', '4f017236-e9f5-4b94-b6ea-148d2efc7df0', '{"en": "Passwords & Phishing"}', '{"en": "Digital identity is about what''s visible; this lesson is about the front door — the password that guards your accounts, and the con artists trying to talk their way past it instead of breaking it down.\n\n## Passwords — The Front Door to Your Digital Life\n\nThink of your password exactly like the key to your house. If that key is easy to copy, or you leave it lying around, anyone can walk right in. Your online accounts work the same way.\n\nHere''s the problem: a huge number of people still use passwords like \"123456,\" \"password,\" or their own birthday. That''s basically hiding your house key under the doormat — anyone who knows to look will find it in seconds.\n\n**How do hackers actually crack passwords?** There''s a method called **brute force**, where software tries millions of combinations per second until it stumbles onto the right one. There''s also a **dictionary attack**, where the software specifically tries common words and known passwords first. The simpler and more common your password, the faster it falls.\n\n**What makes a strong password?**\n- Make it long — at least 12 characters\n- Mix uppercase, lowercase, numbers, and symbols\n- Never use personal info like your name or birthdate\n- Use a different password for every account\n\n\n\n![A weak password versus a strong one](course-media:u1-l2-01-weak-vs-strong-password.png)\n\nIf remembering all that feels like a lot, don''t worry — a password strength checker can tell you exactly how strong your password really is and suggest stronger alternatives.\n\n## Phishing — When the Bait Gets Taken\n\nA strong password still won''t save you if you hand it over willingly — which is exactly what phishing tries to trick you into doing. The name comes from exactly what you think: fishing. An attacker drops \"bait,\" and you''re the fish.\n\nHere''s how it usually plays out. You get a message — an email, a WhatsApp text, even an SMS — that looks completely official and convincing. It might claim to be your bank, a delivery company, or even a friend. The message contains a link and asks you to enter your details or click something urgently, almost always wrapped in pressure like \"Your account will be locked in 24 hours!\" That pressure is deliberate — it''s designed to make you act before you think.\n\n**Warning signs that a message is phishing:**\n- A sense of urgency and pressure (\"Act now or else!\")\n- Spelling or grammar that feels slightly off\n- A link that looks almost right but isn''t quite — like \"Faceb00k\" instead of \"Facebook\"\n- A direct request for sensitive info like your password or card number\n\n\n\n![The anatomy of a phishing attempt: bait, send, click, catch](course-media:u1-l2-02-phishing-anatomy.png)\n\nPhishing is one of attackers'' favorite weapons precisely because it doesn''t require deep technical skill — just a solid understanding of human psychology. Training yourself to spot fake messages with real examples is one of the fastest ways to build this instinct.\n\n## Key Takeaways\n- A strong password is long, random, and unique to each account — never personal information.\n- Phishing messages create urgency on purpose; slow down before you click anything."}', 2),
  ('ff344d49-dfe1-4b19-8c68-7cdf327e09af', '97d4be71-62e3-45e1-aa8f-6818373b90a9', '{"en": "Social Engineering & Malware"}', '{"en": "Attackers have two broad ways in: talk you into helping them, or sneak malicious software onto your device. This lesson covers both — starting with the con, then the code.\n\n## When the Hacker Targets Your Mind, Not Your Machine\n\nRemember phishing from Unit 1? Social engineering is the \"science\" behind it — it''s the art (or really, the manipulation) an attacker uses to convince you to do something or hand over information, without ever needing to technically breach your device at all.\n\n\n\n![Pretexting, baiting, and tailgating](course-media:u2-l1-01-social-engineering-techniques.png)\n\nWhy does this work so well? Because the weakest link in any security system was never the hardware — it''s the human being. No matter how technically solid your defenses are, if an attacker can simply talk you into handing over your own password, all that protection was for nothing.\n\n**How do you protect yourself?**\n- Be suspicious of any unexpected request, even if it claims to come from an official source\n- Verify the person''s identity through a separate channel — call the company directly instead of replying to the email\n- Don''t let yourself be rushed; attackers rely on you acting fast without thinking\n\n## Malware — The Guest You Never Invited Onto Your Device\n\nSometimes attackers skip the conversation entirely and let software do the work instead. **Malware** is short for malicious software — any program built specifically to damage your device or your data. Not all malware works the same way, so let''s break down the main types.\n\n![Virus, worm, trojan, ransomware, and spyware](course-media:u2-l1-02-malware-types.png)\n, so let''s break down the main types.\n\n**Viruses**: attach themselves to another legitimate program and spread when you run that program — just like a real virus spreading from person to person.\n\n**Worms**: similar to viruses, but they spread on their own without needing anyone to run them — moving from device to device directly across a network.\n\n**Trojans**: disguise themselves as something useful or legitimate (a free app or game) while hiding malicious code inside. Remember the Trojan Horse from Greek mythology? Same exact idea — and often delivered through exactly the kind of social engineering we just covered.\n\n**Ransomware**: one of the most dangerous types today — it encrypts all your files and demands payment (a ransom) to unlock them, with zero guarantee you''ll actually get your files back even if you pay.\n\n**Spyware**: silently monitors everything you do on your device, recording every keystroke (a **keylogger**) or even switching on your camera without your knowledge.\n\n**How do you protect yourself?**\n- Don''t download software from untrusted sources\n- Keep your operating system and security software updated constantly\n- Back up your important files regularly — so if ransomware hits, you''re never forced to pay\n\n## Key Takeaways\n- Social engineering targets people, not machines — verify unexpected requests through a separate channel.\n- Malware comes in several forms, but regular backups are your best defense against ransomware specifically."}', 1),
  ('bca05058-aea7-4c0b-b571-4cac810d05aa', '97d4be71-62e3-45e1-aa8f-6818373b90a9', '{"en": "Protecting Your Accounts, Network & Email"}', '{"en": "Now that you know how attackers get in, let''s lock down the three places they usually try: your login, your connection, and your inbox.\n\n## Two-Factor Authentication (2FA) — An Extra Lock on Your Digital Door\n\nWe talked about how important a strong password is — but here''s the truth: even the strongest password in the world can still get stolen. That''s where **two-factor authentication (2FA)** comes in.\n\nThe idea is simple: instead of your account depending on just one thing (your password), it now needs a second thing to confirm it''s really you. That second thing falls into one of three categories:\n- **Something you know**: like your password or a PIN\n- **Something you have**: like your phone receiving a code, or an authenticator app\n- **Something you are**: like your fingerprint or facial recognition\n\nSo even if someone somehow gets your password, they still can''t get in without your phone or your fingerprint too.\n\n**\n\n![How two-factor authentication confirms it''s really you](course-media:u2-l2-01-two-factor-auth-flow.png)\n\nPractical tip:** turn on 2FA for every important account you own — email, banking, social media — and where possible, use an authenticator app rather than SMS, since text messages can be intercepted through an attack called SIM swapping.\n\n## Network Security — Is Public Wi-Fi Friend or Foe?\n\nSitting in a café or an airport, and that free wifi looks tempting? Let''s stop before connecting: public networks are one of the riskiest places you can use the internet.\n\n**Why is public wifi dangerous?** Because anyone else connected to that same network, with just a bit of technical know-how, can \"eavesdrop\" on the data flowing between you and any site you visit. This is called a **man-in-the-middle attack** — the attacker inserts themselves right between you and whatever you''re communicating with, without you ever noticing.\n\n\n\n![A man-in-the-middle attack intercepting your connection](course-media:u2-l2-02-man-in-the-middle.png)\n\nThere''s also an attack called **evil twin**, where the attacker sets up a fake wifi network with a name almost identical to the real one (like \"Cafe_WiFi_Free\" instead of \"Cafe_WiFi\"). Connect without paying attention, and all your data flows straight through them.\n\n**How do you protect yourself on public networks?**\n- Use a **VPN** (virtual private network) — it creates an encrypted tunnel for your data, so even if someone''s eavesdropping, they can''t make sense of anything\n- Avoid logging into sensitive accounts like banking while on public wifi\n- Confirm the exact network name with staff before connecting\n- Make sure **HTTPS** is active (look for the small lock icon next to the site name in your browser)\n\n## Email Security — Spotting a Fake Email\n\nWe covered phishing in general terms in Unit 1 — now let''s go deeper: how do you actually analyze an email to tell if it''s real or not?\n\n**Email headers** carry hidden information — think of it as the email''s passport, showing you where it actually came from, not just the name displayed in the \"From\" field.\n\n\n\n![A real-looking phishing email, annotated](course-media:u2-l2-03-fake-email-example.png)\n\n**Things to check in any suspicious email:**\n- **The actual sender address**: the display name might say \"Support Team,\" but the real email address could be something completely unrelated to the company\n- **The domain**: make sure it exactly matches the company''s real domain — there''s a trick called **typosquatting** where attackers use a domain that''s almost identical but with one letter swapped\n- **Links**: before clicking anything, hover your mouse over the link (without clicking) to see the real destination underneath\n- **Attachments**: be very cautious of unexpected attachments, especially ones with unusual extensions like .exe or .scr\n\n## Key Takeaways\n- Two-factor authentication means a stolen password alone still isn''t enough to get into your account.\n- Public Wi-Fi is convenient but risky — a VPN and HTTPS both help protect your data in transit.\n- Checking the sender''s actual address and hovering over links are the fastest ways to catch a fake email."}', 2),
  ('cccd3cce-2c0d-46ef-86bb-f4a5f23c8dc0', 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', '{"en": "Encryption & Web Vulnerabilities"}', '{"en": "Every technical defense in this unit builds on one idea or another from here: how data gets scrambled so only the right party can read it, and how sloppy handling of user input on a website tears that protection wide open.\n\n## How Your Data Turns Into Gibberish\n\nWe''ve reached a good point to talk about one of the most important concepts in all of cybersecurity: encryption.\n\nSimply put, encryption is the process of transforming data — a message, a file, even a password — from a readable form (**plaintext**) into a completely unreadable form (**ciphertext**), where nobody can reverse it back without the correct \"key.\"\n\n\n\n![Symmetric encryption versus asymmetric encryption](course-media:u3-l1-01-symmetric-vs-asymmetric.png)\n\n**Hashing**: different from encryption in one key way — it''s a one-way process, meaning you can never reverse a hash back into the original data. It''s commonly used to store passwords: instead of a site storing your actual password, it stores only its hash.\n\n**Why should this matter to you as an everyday user?** Because every time you visit an HTTPS site, or send a message on an app that uses **end-to-end encryption**, you''re benefiting from encryption without even noticing. Understanding it helps you tell the difference between a genuinely secure connection and one that isn''t.\n\n## Common Web Vulnerabilities — SQL Injection and XSS\n\nEncryption protects data in transit — but a website also has to handle what people type into it, and that''s its own attack surface. If you''re interested in web development or penetration testing, there are two vulnerabilities you absolutely need to know.\n\n**SQL injection:** imagine a website with a search box or login field that takes whatever you type and drops it directly into a database query without properly checking it first. An attacker can type code into that field instead of normal data, letting them view data they were never meant to see — or even alter or delete data from the entire database.\n\n\n\n![A normal query versus an injected one](course-media:u3-l1-02-sql-injection-example.png)\n\n**Cross-site scripting (XSS):** here, the attacker injects malicious JavaScript code into a web page. When an ordinary user later opens that page, the code runs in their browser — potentially stealing their cookies or performing actions on their behalf without them ever knowing.\n\n**How do developers protect their sites from these vulnerabilities?**\n- **Input validation** — checking every piece of user input before processing it\n- Using **prepared statements** when working with databases\n- **Output encoding** — sanitizing any content before displaying it on the page\n- Running regular **penetration testing** on the site\n\n## Key Takeaways\n- Symmetric encryption uses one shared key; asymmetric uses a public/private pair — HTTPS relies on both.\n- Hashing is one-way by design, which is why it''s used to store passwords instead of encryption.\n- Input validation and prepared statements are the main defenses against SQL injection and XSS."}', 1),
  ('48f8bad0-fd08-43cf-8cd6-bb1e3f8ba1a7', 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', '{"en": "Firewalls, Incident Response & IoT Security"}', '{"en": "The last stretch covers three things every organization (and honestly, every household) needs: something to filter traffic, a plan for when things go wrong anyway, and awareness that your smart devices are part of the attack surface too.\n\n## Firewalls and Intrusion Detection Systems\n\nThink of a **firewall** like a security guard standing at a building''s entrance — their job is to watch everyone coming in and going out, and decide who''s allowed based on a set of agreed-upon rules.\n\nA firewall works by monitoring the **traffic** flowing in and out of your device or network. If it spots suspicious activity that breaks the rules, it blocks it before it goes any further.\n\n**There''s also intrusion detection systems (IDS) and intrusion prevention systems (IPS):** an **IDS** monitors the network and alerts you when something suspicious happens — but it doesn''t step in to stop it itself. An **IPS** goes a step further: it doesn''t just detect suspicious activity, it takes immediate action to block it.\n\n\n\n![The layers of defense in depth, from firewall to user awareness](course-media:u3-l2-01-defense-in-depth-layers.png)\n\n**Why do all these layers matter?** In cybersecurity, we rely on a principle called **defense in depth** — layered defense. We never depend on just one thing to protect us, because if that one layer gets breached, there''s nothing left standing behind it.\n\n## Incident Response — A Breach Just Happened, Now What?\n\nNo matter how strong your layers of protection are, you always need to be ready for the scenario where a breach actually happens — because that readiness is what separates a small setback from a genuine disaster.\n\n**The incident response process, simplified:**\n- **Identification**: how did you even find out a breach happened?\n- **Containment**: the very first thing you do — disconnect the affected device from the network immediately.\n- **Eradication**: remove the root cause of the problem.\n- **Recovery**: restore the system to its normal state, ideally from a clean backup.\n- **Lessons learned**: once the crisis is over, ask yourself how to prevent it happening again.\n\n\n\n![The five phases of incident response](course-media:u3-l2-02-incident-response-phases.png)\n\n**Why does this matter even on a personal level?** If your account ever gets breached or your device gets infected, knowing these steps means you can act calmly and logically instead of panicking — and that''s what actually limits the damage.\n\n## IoT Security\n\nWe touched on IoT devices (Internet of Things) in Unit 1 — smart cameras, smartwatches, even internet-connected fridges and washing machines that have become part of our daily lives. Now let''s understand why these devices specifically pose such a major security challenge.\n\n**Why are IoT devices security risks?**\n- They often ship with a **default password**, and most users never change it\n- Not every manufacturer regularly updates the software on these devices\n- A massive number of these devices are online simultaneously, making them an attractive target for building large-scale attack networks (**botnets**)\n\n\n\n![A botnet of compromised IoT devices flooding a target server](course-media:u3-l2-03-iot-botnet-ddos.png)\n\n**How do you protect your IoT devices?**\n- Change the default password immediately when you buy any new device\n- Update the device''s software regularly if the manufacturer provides updates\n- Disconnect any device you''re not actually using from the internet\n- Where possible, keep IoT devices on a separate wifi network from your main devices\n\n## Key Takeaways\n- Defense in depth means layering a firewall, IDS/IPS, 2FA, and user awareness, so no single failure is fatal.\n- The five phases of incident response are identification, containment, eradication, recovery, and lessons learned.\n- IoT devices are risky mainly because of unchanged default passwords — change them the moment you set one up."}', 2);
insert into public.assessment_questions (kind, lesson_id, unit_id, course_id, prompt, choices, correct_choice_id, hint, order_index) values
  ('quick_check', '3e536c0f-0d9a-44d8-9058-22558a674248', null, null, '{"en": "What is included in your digital identity besides what you consciously post?"}', '[{"id": "a", "text": {"en": "Only your profile picture"}}, {"id": "b", "text": {"en": "Nothing else matters"}}, {"id": "c", "text": {"en": "Things like login times, devices used, and location data too"}}, {"id": "d", "text": {"en": "Just your username"}}]', 'c', null, 1),
  ('quick_check', '3e536c0f-0d9a-44d8-9058-22558a674248', null, null, '{"en": "What is impersonation in the context of social media?"}', '[{"id": "a", "text": {"en": "Changing your own profile picture"}}, {"id": "b", "text": {"en": "Reporting a post"}}, {"id": "c", "text": {"en": "Someone creating a fake account pretending to be you"}}, {"id": "d", "text": {"en": "Blocking a user"}}]', 'c', null, 2),
  ('quick_check', '3e536c0f-0d9a-44d8-9058-22558a674248', null, null, '{"en": "Once something is posted online and shared, it''s generally:"}', '[{"id": "a", "text": {"en": "Easy to fully erase everywhere"}}, {"id": "b", "text": {"en": "Automatically deleted after a day"}}, {"id": "c", "text": {"en": "Only visible to you"}}, {"id": "d", "text": {"en": "Very hard to fully remove or control once it spreads"}}]', 'd', null, 3),
  ('quick_check', '556c8347-176c-4941-88e9-a73d04f5f6a6', null, null, '{"en": "What''s the minimum recommended password length in this lesson?"}', '[{"id": "a", "text": {"en": "4 characters"}}, {"id": "b", "text": {"en": "12 characters"}}, {"id": "c", "text": {"en": "8 characters"}}, {"id": "d", "text": {"en": "It doesn''t matter"}}]', 'b', null, 1),
  ('quick_check', '556c8347-176c-4941-88e9-a73d04f5f6a6', null, null, '{"en": "Why is \"password123\" considered weak?"}', '[{"id": "a", "text": {"en": "It''s too long"}}, {"id": "b", "text": {"en": "It has too many symbols"}}, {"id": "c", "text": {"en": "It''s a common, easily guessed pattern"}}, {"id": "d", "text": {"en": "It''s actually strong"}}]', 'c', null, 2),
  ('quick_check', '556c8347-176c-4941-88e9-a73d04f5f6a6', null, null, '{"en": "What''s a common red flag in a phishing link?"}', '[{"id": "a", "text": {"en": "It matches the real site exactly"}}, {"id": "b", "text": {"en": "It has no link at all"}}, {"id": "c", "text": {"en": "It''s from a verified account"}}, {"id": "d", "text": {"en": "It looks almost right but has a small difference, like \"Faceb00k\""}}]', 'd', null, 3),
  ('quick_check', 'ff344d49-dfe1-4b19-8c68-7cdf327e09af', null, null, '{"en": "What is the weakest link in most security systems, according to this lesson?"}', '[{"id": "a", "text": {"en": "The human being"}}, {"id": "b", "text": {"en": "The network"}}, {"id": "c", "text": {"en": "The hardware"}}, {"id": "d", "text": {"en": "The software"}}]', 'a', null, 1),
  ('quick_check', 'ff344d49-dfe1-4b19-8c68-7cdf327e09af', null, null, '{"en": "What does ransomware do?"}', '[{"id": "a", "text": {"en": "Encrypts your files and demands payment"}}, {"id": "b", "text": {"en": "Speeds up your device"}}, {"id": "c", "text": {"en": "Removes other viruses"}}, {"id": "d", "text": {"en": "Improves your wifi"}}]', 'a', null, 2),
  ('quick_check', 'ff344d49-dfe1-4b19-8c68-7cdf327e09af', null, null, '{"en": "What''s the best defense against ransomware?"}', '[{"id": "a", "text": {"en": "Paying immediately"}}, {"id": "b", "text": {"en": "Regular backups of important files"}}, {"id": "c", "text": {"en": "Ignoring it"}}, {"id": "d", "text": {"en": "Changing your username"}}]', 'b', null, 3),
  ('quick_check', 'bca05058-aea7-4c0b-b571-4cac810d05aa', null, null, '{"en": "2FA requires:"}', '[{"id": "a", "text": {"en": "Just a password"}}, {"id": "b", "text": {"en": "No password at all"}}, {"id": "c", "text": {"en": "Two passwords only"}}, {"id": "d", "text": {"en": "A password plus a second verification factor"}}]', 'd', null, 1),
  ('quick_check', 'bca05058-aea7-4c0b-b571-4cac810d05aa', null, null, '{"en": "What does a VPN do on public wifi?"}', '[{"id": "a", "text": {"en": "Creates an encrypted tunnel for your data"}}, {"id": "b", "text": {"en": "Slows down your connection only"}}, {"id": "c", "text": {"en": "Removes all viruses"}}, {"id": "d", "text": {"en": "Blocks every website"}}]', 'a', null, 2),
  ('quick_check', 'bca05058-aea7-4c0b-b571-4cac810d05aa', null, null, '{"en": "Before clicking a link in a suspicious email, you should:"}', '[{"id": "a", "text": {"en": "Click it immediately"}}, {"id": "b", "text": {"en": "Hover over it to check the real destination first"}}, {"id": "c", "text": {"en": "Reply asking for more info"}}, {"id": "d", "text": {"en": "Forward it to a friend first"}}]', 'b', null, 3),
  ('quick_check', 'cccd3cce-2c0d-46ef-86bb-f4a5f23c8dc0', null, null, '{"en": "Why can''t a hashed password be reversed back to the original?"}', '[{"id": "a", "text": {"en": "It uses two keys"}}, {"id": "b", "text": {"en": "It''s actually reversible"}}, {"id": "c", "text": {"en": "Hashing doesn''t apply to passwords"}}, {"id": "d", "text": {"en": "Hashing is a one-way process"}}]', 'd', null, 1),
  ('quick_check', 'cccd3cce-2c0d-46ef-86bb-f4a5f23c8dc0', null, null, '{"en": "SQL injection happens when:"}', '[{"id": "a", "text": {"en": "A site takes user input and drops it directly into a database query without proper checks"}}, {"id": "b", "text": {"en": "A developer properly validates all user input"}}, {"id": "c", "text": {"en": "A user uses a strong password"}}, {"id": "d", "text": {"en": "A site uses HTTPS"}}]', 'a', null, 2),
  ('quick_check', 'cccd3cce-2c0d-46ef-86bb-f4a5f23c8dc0', null, null, '{"en": "What helps prevent SQL injection?"}', '[{"id": "a", "text": {"en": "Ignoring user input"}}, {"id": "b", "text": {"en": "Weak passwords"}}, {"id": "c", "text": {"en": "Prepared statements"}}, {"id": "d", "text": {"en": "Removing HTTPS"}}]', 'c', null, 3),
  ('quick_check', '48f8bad0-fd08-43cf-8cd6-bb1e3f8ba1a7', null, null, '{"en": "What''s the difference between IDS and IPS?"}', '[{"id": "a", "text": {"en": "IDS only alerts; IPS actively blocks threats"}}, {"id": "b", "text": {"en": "No difference"}}, {"id": "c", "text": {"en": "IPS only alerts; IDS blocks"}}, {"id": "d", "text": {"en": "IDS encrypts data"}}]', 'a', null, 1),
  ('quick_check', '48f8bad0-fd08-43cf-8cd6-bb1e3f8ba1a7', null, null, '{"en": "What''s the first step after detecting a breach?"}', '[{"id": "a", "text": {"en": "Ignoring it"}}, {"id": "b", "text": {"en": "Containment"}}, {"id": "c", "text": {"en": "Buying new hardware"}}, {"id": "d", "text": {"en": "Posting online about it"}}]', 'b', null, 2),
  ('quick_check', '48f8bad0-fd08-43cf-8cd6-bb1e3f8ba1a7', null, null, '{"en": "Best practice for a new IoT device is to:"}', '[{"id": "a", "text": {"en": "Keep the default password"}}, {"id": "b", "text": {"en": "Never update it"}}, {"id": "c", "text": {"en": "Connect it to every network"}}, {"id": "d", "text": {"en": "Change the default password immediately"}}]', 'd', null, 3);
insert into public.assessment_questions (kind, lesson_id, unit_id, course_id, prompt, choices, correct_choice_id, hint, order_index) values
  ('unit_exam', null, '4f017236-e9f5-4b94-b6ea-148d2efc7df0', null, '{"en": "Cybersecurity means:"}', '[{"id": "a", "text": {"en": "Protecting individuals and organizations from cyberattacks"}}, {"id": "b", "text": {"en": "Internet connection speed"}}, {"id": "c", "text": {"en": "A type of virus"}}, {"id": "d", "text": {"en": "A web browsing app"}}]', 'a', null, 1),
  ('unit_exam', null, '4f017236-e9f5-4b94-b6ea-148d2efc7df0', null, '{"en": "Besides what you consciously post, your digital identity also includes:"}', '[{"id": "a", "text": {"en": "Nothing else — only your posts count"}}, {"id": "b", "text": {"en": "Login times, devices used, and location data"}}, {"id": "c", "text": {"en": "Just your profile picture"}}, {"id": "d", "text": {"en": "Only your follower count"}}]', 'b', null, 2),
  ('unit_exam', null, '4f017236-e9f5-4b94-b6ea-148d2efc7df0', null, '{"en": "What is a brute force attack?"}', '[{"id": "a", "text": {"en": "A firewall setting"}}, {"id": "b", "text": {"en": "Software trying millions of password combinations until one works"}}, {"id": "c", "text": {"en": "A type of encryption"}}, {"id": "d", "text": {"en": "A social media privacy feature"}}]', 'b', null, 3),
  ('unit_exam', null, '4f017236-e9f5-4b94-b6ea-148d2efc7df0', null, '{"en": "The minimum recommended password length covered in this unit is:"}', '[{"id": "a", "text": {"en": "6 characters"}}, {"id": "b", "text": {"en": "8 characters"}}, {"id": "c", "text": {"en": "12 characters"}}, {"id": "d", "text": {"en": "20 characters"}}]', 'c', null, 4),
  ('unit_exam', null, '4f017236-e9f5-4b94-b6ea-148d2efc7df0', null, '{"en": "A phishing message typically tries to make you act fast by creating:"}', '[{"id": "a", "text": {"en": "Boredom"}}, {"id": "b", "text": {"en": "A sense of urgency"}}, {"id": "c", "text": {"en": "Confusion"}}, {"id": "d", "text": {"en": "Curiosity only"}}]', 'b', null, 5),
  ('unit_exam', null, '4f017236-e9f5-4b94-b6ea-148d2efc7df0', null, '{"en": "A link that looks almost right but has a subtle difference, like \"Faceb00k,\" is a sign of:"}', '[{"id": "a", "text": {"en": "A verified account"}}, {"id": "b", "text": {"en": "Phishing"}}, {"id": "c", "text": {"en": "A secure connection"}}, {"id": "d", "text": {"en": "A strong password"}}]', 'b', null, 6),
  ('unit_exam', null, '4f017236-e9f5-4b94-b6ea-148d2efc7df0', null, '{"en": "Phishing works mainly by exploiting:"}', '[{"id": "a", "text": {"en": "Software bugs"}}, {"id": "b", "text": {"en": "Hardware failures"}}, {"id": "c", "text": {"en": "Human psychology and trust"}}, {"id": "d", "text": {"en": "Slow internet speeds"}}]', 'c', null, 7),
  ('unit_exam', null, '4f017236-e9f5-4b94-b6ea-148d2efc7df0', null, '{"en": "Creating a fake account under someone else''s name to scam their friends is called:"}', '[{"id": "a", "text": {"en": "Tailgating"}}, {"id": "b", "text": {"en": "Impersonation"}}, {"id": "c", "text": {"en": "Encryption"}}, {"id": "d", "text": {"en": "Hashing"}}]', 'b', null, 8),
  ('unit_exam', null, '4f017236-e9f5-4b94-b6ea-148d2efc7df0', null, '{"en": "Which of these is risky to post in a photo on social media?"}', '[{"id": "a", "text": {"en": "A landscape"}}, {"id": "b", "text": {"en": "A meal you cooked"}}, {"id": "c", "text": {"en": "A photo showing your passport or ID"}}, {"id": "d", "text": {"en": "A book you''re reading"}}]', 'c', null, 9),
  ('unit_exam', null, '4f017236-e9f5-4b94-b6ea-148d2efc7df0', null, '{"en": "Why should you regularly review your privacy settings on social media?"}', '[{"id": "a", "text": {"en": "To increase your follower count"}}, {"id": "b", "text": {"en": "Platforms force you to"}}, {"id": "c", "text": {"en": "There''s no need to ever review them"}}, {"id": "d", "text": {"en": "To control who can see your information and content"}}]', 'd', null, 10),
  ('unit_exam', null, '4f017236-e9f5-4b94-b6ea-148d2efc7df0', null, '{"en": "Once content is posted and shared online, it is generally:"}', '[{"id": "a", "text": {"en": "Easy to fully erase everywhere"}}, {"id": "b", "text": {"en": "Very hard to fully remove or control once it spreads"}}, {"id": "c", "text": {"en": "Automatically deleted after a day"}}, {"id": "d", "text": {"en": "Only ever visible to you"}}]', 'b', null, 11),
  ('unit_exam', null, '4f017236-e9f5-4b94-b6ea-148d2efc7df0', null, '{"en": "Using a different password for every account mainly protects you by:"}', '[{"id": "a", "text": {"en": "Making passwords easier to remember"}}, {"id": "b", "text": {"en": "Ensuring one breached account doesn''t put your other accounts at risk"}}, {"id": "c", "text": {"en": "Speeding up your login"}}, {"id": "d", "text": {"en": "Being required by law"}}]', 'b', null, 12),
  ('unit_exam', null, '4f017236-e9f5-4b94-b6ea-148d2efc7df0', null, '{"en": "Reusing the same username across every platform mainly increases the risk of:"}', '[{"id": "a", "text": {"en": "Making your account more secure"}}, {"id": "b", "text": {"en": "Slowing down your login speed"}}, {"id": "c", "text": {"en": "There being no real risk"}}, {"id": "d", "text": {"en": "Making it easy for anyone to link your different accounts and build a profile on you"}}]', 'd', null, 13),
  ('unit_exam', null, '97d4be71-62e3-45e1-aa8f-6818373b90a9', null, '{"en": "Fabricating a false story or identity to earn a victim''s trust is called:"}', '[{"id": "a", "text": {"en": "Baiting"}}, {"id": "b", "text": {"en": "Pretexting"}}, {"id": "c", "text": {"en": "Tailgating"}}, {"id": "d", "text": {"en": "Phishing"}}]', 'b', null, 1),
  ('unit_exam', null, '97d4be71-62e3-45e1-aa8f-6818373b90a9', null, '{"en": "Leaving an infected USB drive in a public place hoping someone plugs it in is called:"}', '[{"id": "a", "text": {"en": "Baiting"}}, {"id": "b", "text": {"en": "Pretexting"}}, {"id": "c", "text": {"en": "Tailgating"}}, {"id": "d", "text": {"en": "Phishing"}}]', 'a', null, 2),
  ('unit_exam', null, '97d4be71-62e3-45e1-aa8f-6818373b90a9', null, '{"en": "According to this course, what is the weakest link in most security systems?"}', '[{"id": "a", "text": {"en": "The network"}}, {"id": "b", "text": {"en": "The software"}}, {"id": "c", "text": {"en": "The hardware"}}, {"id": "d", "text": {"en": "The human being"}}]', 'd', null, 3),
  ('unit_exam', null, '97d4be71-62e3-45e1-aa8f-6818373b90a9', null, '{"en": "The key difference between a virus and a worm is:"}', '[{"id": "a", "text": {"en": "There''s no real difference"}}, {"id": "b", "text": {"en": "A virus is always more dangerous than a worm"}}, {"id": "c", "text": {"en": "A worm spreads on its own without needing a user to run anything, while a virus needs a host program run by the user"}}, {"id": "d", "text": {"en": "Worms only infect phones"}}]', 'c', null, 4),
  ('unit_exam', null, '97d4be71-62e3-45e1-aa8f-6818373b90a9', null, '{"en": "What does ransomware actually do?"}', '[{"id": "a", "text": {"en": "Encrypts your files and demands payment to unlock them"}}, {"id": "b", "text": {"en": "Speeds up your device"}}, {"id": "c", "text": {"en": "Improves battery performance"}}, {"id": "d", "text": {"en": "Removes other viruses"}}]', 'a', null, 5),
  ('unit_exam', null, '97d4be71-62e3-45e1-aa8f-6818373b90a9', null, '{"en": "The best defense against ransomware is:"}', '[{"id": "a", "text": {"en": "Paying the ransom immediately if it happens"}}, {"id": "b", "text": {"en": "Ignoring the issue entirely"}}, {"id": "c", "text": {"en": "Just changing your password"}}, {"id": "d", "text": {"en": "Keeping regular backups of your important files"}}]', 'd', null, 6),
  ('unit_exam', null, '97d4be71-62e3-45e1-aa8f-6818373b90a9', null, '{"en": "Two-factor authentication (2FA) adds to your account:"}', '[{"id": "a", "text": {"en": "Faster browsing speed"}}, {"id": "b", "text": {"en": "An extra layer of security beyond your password"}}, {"id": "c", "text": {"en": "More storage space"}}, {"id": "d", "text": {"en": "No real benefit"}}]', 'b', null, 7),
  ('unit_exam', null, '97d4be71-62e3-45e1-aa8f-6818373b90a9', null, '{"en": "Why is an authenticator app generally safer than SMS for 2FA?"}', '[{"id": "a", "text": {"en": "SMS is faster"}}, {"id": "b", "text": {"en": "The app is simply free"}}, {"id": "c", "text": {"en": "SMS messages can be intercepted through SIM swapping"}}, {"id": "d", "text": {"en": "There''s no real difference"}}]', 'c', null, 8),
  ('unit_exam', null, '97d4be71-62e3-45e1-aa8f-6818373b90a9', null, '{"en": "An attack where the attacker inserts themselves between you and the website you''re visiting to intercept your data is called:"}', '[{"id": "a", "text": {"en": "Brute force"}}, {"id": "b", "text": {"en": "Ransomware"}}, {"id": "c", "text": {"en": "Trojan"}}, {"id": "d", "text": {"en": "Man-in-the-middle attack"}}]', 'd', null, 9),
  ('unit_exam', null, '97d4be71-62e3-45e1-aa8f-6818373b90a9', null, '{"en": "A fake wifi network designed to closely mimic the name of a real one is known as:"}', '[{"id": "a", "text": {"en": "Zero-day"}}, {"id": "b", "text": {"en": "Evil twin"}}, {"id": "c", "text": {"en": "Keylogging"}}, {"id": "d", "text": {"en": "Tailgating"}}]', 'b', null, 10),
  ('unit_exam', null, '97d4be71-62e3-45e1-aa8f-6818373b90a9', null, '{"en": "How does a VPN help you on public wifi?"}', '[{"id": "a", "text": {"en": "It only increases internet speed"}}, {"id": "b", "text": {"en": "It removes viruses"}}, {"id": "c", "text": {"en": "It creates an encrypted tunnel that makes your data much harder to intercept"}}, {"id": "d", "text": {"en": "It blocks you from visiting any website"}}]', 'c', null, 11),
  ('unit_exam', null, '97d4be71-62e3-45e1-aa8f-6818373b90a9', null, '{"en": "The hidden information that reveals an email''s true origin is called:"}', '[{"id": "a", "text": {"en": "Email body"}}, {"id": "b", "text": {"en": "Email signature"}}, {"id": "c", "text": {"en": "Email attachment"}}, {"id": "d", "text": {"en": "Email headers"}}]', 'd', null, 12),
  ('unit_exam', null, '97d4be71-62e3-45e1-aa8f-6818373b90a9', null, '{"en": "Using a domain nearly identical to a real company''s, with a subtle typo, is a trick called:"}', '[{"id": "a", "text": {"en": "Baiting"}}, {"id": "b", "text": {"en": "Tailgating"}}, {"id": "c", "text": {"en": "Typosquatting"}}, {"id": "d", "text": {"en": "Voice spoofing"}}]', 'c', null, 13),
  ('unit_exam', null, 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', null, '{"en": "Symmetric encryption relies on:"}', '[{"id": "a", "text": {"en": "Two different keys for encrypting and decrypting"}}, {"id": "b", "text": {"en": "No key at all"}}, {"id": "c", "text": {"en": "A one-way process only"}}, {"id": "d", "text": {"en": "The same key for both encrypting and decrypting"}}]', 'd', null, 1),
  ('unit_exam', null, 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', null, '{"en": "Asymmetric encryption uses:"}', '[{"id": "a", "text": {"en": "A public key and a private key"}}, {"id": "b", "text": {"en": "Only one shared key"}}, {"id": "c", "text": {"en": "A single password for all users"}}, {"id": "d", "text": {"en": "No keys whatsoever"}}]', 'a', null, 2),
  ('unit_exam', null, 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', null, '{"en": "Hashing differs from regular encryption because:"}', '[{"id": "a", "text": {"en": "It''s much faster than any encryption"}}, {"id": "b", "text": {"en": "It uses two keys"}}, {"id": "c", "text": {"en": "It''s a one-way process that can''t be reversed back to the original data"}}, {"id": "d", "text": {"en": "It''s never used to protect passwords"}}]', 'c', null, 3),
  ('unit_exam', null, 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', null, '{"en": "SQL injection happens when:"}', '[{"id": "a", "text": {"en": "A developer properly validates all user input"}}, {"id": "b", "text": {"en": "A site takes user input and drops it directly into a database query without proper checks"}}, {"id": "c", "text": {"en": "A user uses a strong password"}}, {"id": "d", "text": {"en": "A site uses HTTPS"}}]', 'b', null, 4),
  ('unit_exam', null, 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', null, '{"en": "Cross-site scripting (XSS) allows an attacker to:"}', '[{"id": "a", "text": {"en": "Speed up a website"}}, {"id": "b", "text": {"en": "Improve a website''s design"}}, {"id": "c", "text": {"en": "Only delete a database directly"}}, {"id": "d", "text": {"en": "Inject malicious JavaScript that runs in other users'' browsers"}}]', 'd', null, 5),
  ('unit_exam', null, 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', null, '{"en": "Input validation in web development helps protect against:"}', '[{"id": "a", "text": {"en": "Vulnerabilities like SQL injection and XSS"}}, {"id": "b", "text": {"en": "Slow internet speeds"}}, {"id": "c", "text": {"en": "Higher hosting costs"}}, {"id": "d", "text": {"en": "It has nothing to do with security"}}]', 'a', null, 6),
  ('unit_exam', null, 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', null, '{"en": "What is a firewall''s primary job?"}', '[{"id": "a", "text": {"en": "Speed up your internet connection"}}, {"id": "b", "text": {"en": "Store your passwords"}}, {"id": "c", "text": {"en": "Monitor incoming and outgoing traffic and control it based on rules"}}, {"id": "d", "text": {"en": "Encrypt files only"}}]', 'c', null, 7),
  ('unit_exam', null, 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', null, '{"en": "The main difference between IDS and IPS is:"}', '[{"id": "a", "text": {"en": "There''s no real difference"}}, {"id": "b", "text": {"en": "IDS detects and alerts only, while IPS takes immediate action to block the threat"}}, {"id": "c", "text": {"en": "IPS only monitors without ever intervening"}}, {"id": "d", "text": {"en": "IDS encrypts data"}}]', 'b', null, 8),
  ('unit_exam', null, 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', null, '{"en": "The first step after detecting a security incident is:"}', '[{"id": "a", "text": {"en": "Deleting all data immediately"}}, {"id": "b", "text": {"en": "Ignoring it entirely"}}, {"id": "c", "text": {"en": "Paying a ransom right away if one is demanded"}}, {"id": "d", "text": {"en": "Containment — disconnecting the affected device from the network immediately"}}]', 'd', null, 9),
  ('unit_exam', null, 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', null, '{"en": "The \"lessons learned\" phase of incident response happens:"}', '[{"id": "a", "text": {"en": "After the crisis is resolved, to understand how to prevent it happening again"}}, {"id": "b", "text": {"en": "Before the incident even occurs"}}, {"id": "c", "text": {"en": "It has nothing to do with future protection"}}, {"id": "d", "text": {"en": "At the exact same moment as the breach"}}]', 'a', null, 10),
  ('unit_exam', null, 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', null, '{"en": "A botnet is:"}', '[{"id": "a", "text": {"en": "Strong security software"}}, {"id": "b", "text": {"en": "A type of VPN"}}, {"id": "c", "text": {"en": "A network of compromised devices controlled together by an attacker"}}, {"id": "d", "text": {"en": "A high-spec IoT device"}}]', 'c', null, 11),
  ('unit_exam', null, 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', null, '{"en": "The best security advice for any new IoT device you buy is to:"}', '[{"id": "a", "text": {"en": "Leave the default password as-is"}}, {"id": "b", "text": {"en": "Change the default password immediately"}}, {"id": "c", "text": {"en": "Connect it to every available network"}}, {"id": "d", "text": {"en": "Never update its software"}}]', 'b', null, 12),
  ('unit_exam', null, 'beb9fe14-553e-48c5-9ea0-dd8c0faac639', null, '{"en": "The main goal of the \"eradication\" phase in incident response is to:"}', '[{"id": "a", "text": {"en": "Post about the breach on social media"}}, {"id": "b", "text": {"en": "Remove the root cause of the breach, like deleting the malicious file or closing the vulnerability"}}, {"id": "c", "text": {"en": "Ignore the problem and wait it out"}}, {"id": "d", "text": {"en": "Immediately buy new hardware"}}]', 'b', null, 13);
insert into public.assessment_questions (kind, lesson_id, unit_id, course_id, prompt, choices, correct_choice_id, hint, order_index) values
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Understanding common vulnerabilities like SQL injection and XSS mainly helps a non-developer user to:"}', '[{"id": "a", "text": {"en": "Write their own malware"}}, {"id": "b", "text": {"en": "Bypass a website''s login page"}}, {"id": "c", "text": {"en": "It offers no benefit to non-developers at all"}}, {"id": "d", "text": {"en": "Better judge how secure a website is and make smarter decisions about their data"}}]', 'd', null, 1),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Which statement about IDS is accurate?"}', '[{"id": "a", "text": {"en": "It automatically blocks every threat it detects"}}, {"id": "b", "text": {"en": "It''s the same thing as a firewall"}}, {"id": "c", "text": {"en": "It detects and alerts on suspicious activity but doesn''t intervene directly"}}, {"id": "d", "text": {"en": "It only works on IoT devices"}}]', 'c', null, 2),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "IoT devices are considered a security challenge mainly because they:"}', '[{"id": "a", "text": {"en": "Are basically impossible to hack"}}, {"id": "b", "text": {"en": "Often ship with a default password that many users never change"}}, {"id": "c", "text": {"en": "Aren''t connected to the internet"}}, {"id": "d", "text": {"en": "Update themselves automatically every day"}}]', 'b', null, 3),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Which of the following is an example of an IoT device?"}', '[{"id": "a", "text": {"en": "A paper notebook"}}, {"id": "b", "text": {"en": "A smart, internet-connected security camera"}}, {"id": "c", "text": {"en": "A pencil"}}, {"id": "d", "text": {"en": "A printed book"}}]', 'b', null, 4),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "A message urging you to \"act immediately or lose access\" is most likely a sign of:"}', '[{"id": "a", "text": {"en": "A routine, harmless notification"}}, {"id": "b", "text": {"en": "A software update"}}, {"id": "c", "text": {"en": "A backup confirmation"}}, {"id": "d", "text": {"en": "A social engineering or phishing attempt exploiting urgency"}}]', 'd', null, 5),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "If an app uses end-to-end encryption, that means:"}', '[{"id": "a", "text": {"en": "Messages aren''t encrypted at all"}}, {"id": "b", "text": {"en": "Messages get sent to a government server first"}}, {"id": "c", "text": {"en": "There''s no real encryption happening"}}, {"id": "d", "text": {"en": "Messages are encrypted from sender to receiver only, and no one in between can read them"}}]', 'd', null, 6),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "An attacker tricks you into revealing your password over a fake tech-support call, then uses it to install ransomware on your device. Which two techniques from this course does that combine?"}', '[{"id": "a", "text": {"en": "Social engineering and malware"}}, {"id": "b", "text": {"en": "SQL injection and XSS"}}, {"id": "c", "text": {"en": "Zero-day exploitation and firewall bypass"}}, {"id": "d", "text": {"en": "VPN spoofing and hashing"}}]', 'a', null, 7),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "In the layered \"defense in depth\" model, which of these would count as one of the layers?"}', '[{"id": "a", "text": {"en": "All of the above"}}, {"id": "b", "text": {"en": "A firewall"}}, {"id": "c", "text": {"en": "Two-factor authentication"}}, {"id": "d", "text": {"en": "User awareness and training"}}]', 'a', null, 8),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "What does the term Cybersecurity mean?"}', '[{"id": "a", "text": {"en": "Protecting individuals and organizations from cyberattacks"}}, {"id": "b", "text": {"en": "Internet connection speed"}}, {"id": "c", "text": {"en": "A type of virus"}}, {"id": "d", "text": {"en": "A web browsing app"}}]', 'a', null, 9),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "If someone suddenly asks for your personal information through an unexpected message, the best move is to:"}', '[{"id": "a", "text": {"en": "Reply quickly so you don''t miss the opportunity"}}, {"id": "b", "text": {"en": "Hand over the information since they asked politely"}}, {"id": "c", "text": {"en": "Block them without checking anything"}}, {"id": "d", "text": {"en": "Verify their identity and give no information until you''re sure"}}]', 'd', null, 10),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "If you receive an unexpected call from someone claiming to be \"IT support\" asking for your password, you should:"}', '[{"id": "a", "text": {"en": "Give it to them since they sound official"}}, {"id": "b", "text": {"en": "Verify their identity independently before sharing anything"}}, {"id": "c", "text": {"en": "Give them a fake password to test them"}}, {"id": "d", "text": {"en": "Ignore the call and never verify who it actually was"}}]', 'b', null, 11),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Why do IoT botnets pose a larger-scale threat than a single infected computer?"}', '[{"id": "a", "text": {"en": "Because IoT devices are always more powerful than computers"}}, {"id": "b", "text": {"en": "Because a massive number of compromised devices can be controlled together to launch a much bigger attack"}}, {"id": "c", "text": {"en": "Because botnets can only affect one device at a time"}}, {"id": "d", "text": {"en": "Because IoT devices are never connected to the internet"}}]', 'b', null, 12),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Which of these is an example of \"something you have\" in 2FA?"}', '[{"id": "a", "text": {"en": "Your fingerprint"}}, {"id": "b", "text": {"en": "Your password"}}, {"id": "c", "text": {"en": "An authenticator app on your phone"}}, {"id": "d", "text": {"en": "Your username"}}]', 'c', null, 13),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "HTTPS relies primarily on:"}', '[{"id": "a", "text": {"en": "Asymmetric encryption"}}, {"id": "b", "text": {"en": "No encryption at all"}}, {"id": "c", "text": {"en": "Deliberately slow connections"}}, {"id": "d", "text": {"en": "One shared password for every site"}}]', 'a', null, 14),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Why can''t a password''s hash be reversed back to the original password?"}', '[{"id": "a", "text": {"en": "Because hashes are always encrypted twice"}}, {"id": "b", "text": {"en": "Because hashing is intentionally a one-way process"}}, {"id": "c", "text": {"en": "Because passwords are never hashed"}}, {"id": "d", "text": {"en": "Because hashing uses a public key"}}]', 'b', null, 15),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Which attachment file extension is a red flag in an unexpected email?"}', '[{"id": "a", "text": {"en": ".jpg"}}, {"id": "b", "text": {"en": ".txt"}}, {"id": "c", "text": {"en": ".exe"}}, {"id": "d", "text": {"en": ".pdf (from a trusted source)"}}]', 'c', null, 16),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Before clicking a link in a suspicious email, the best move is to:"}', '[{"id": "a", "text": {"en": "Hover over it without clicking to reveal the real destination"}}, {"id": "b", "text": {"en": "Click it right away to see what it is"}}, {"id": "c", "text": {"en": "Forward it to friends first"}}, {"id": "d", "text": {"en": "Delete the email without checking anything"}}]', 'a', null, 17),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Output encoding is used to protect against which vulnerability specifically?"}', '[{"id": "a", "text": {"en": "SQL injection only"}}, {"id": "b", "text": {"en": "Cross-site scripting (XSS)"}}, {"id": "c", "text": {"en": "Ransomware"}}, {"id": "d", "text": {"en": "Man-in-the-middle attacks"}}]', 'b', null, 18),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Public wifi is risky mainly because:"}', '[{"id": "a", "text": {"en": "It''s always slower than home networks"}}, {"id": "b", "text": {"en": "It costs money to use"}}, {"id": "c", "text": {"en": "It automatically installs malware on connection"}}, {"id": "d", "text": {"en": "Others on the same network can potentially intercept your data"}}]', 'd', null, 19),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Which combination offers the strongest everyday account protection based on this course?"}', '[{"id": "a", "text": {"en": "A strong, unique password plus 2FA enabled"}}, {"id": "b", "text": {"en": "A weak password alone"}}, {"id": "c", "text": {"en": "The same password reused everywhere"}}, {"id": "d", "text": {"en": "No extra protection beyond a password"}}]', 'a', null, 20),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Why should you use a different password for every account?"}', '[{"id": "a", "text": {"en": "So they''re easier to remember"}}, {"id": "b", "text": {"en": "Websites require it"}}, {"id": "c", "text": {"en": "There''s no real reason"}}, {"id": "d", "text": {"en": "So one breached account doesn''t put all your other accounts at risk"}}]', 'd', null, 21),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Following someone through a secured door without using your own access card is called:"}', '[{"id": "a", "text": {"en": "Pretexting"}}, {"id": "b", "text": {"en": "Tailgating"}}, {"id": "c", "text": {"en": "Baiting"}}, {"id": "d", "text": {"en": "Phishing"}}]', 'b', null, 22),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "A DDoS attack aims to:"}', '[{"id": "a", "text": {"en": "Flood a server with massive fake traffic until it collapses and becomes unavailable"}}, {"id": "b", "text": {"en": "Speed up a server"}}, {"id": "c", "text": {"en": "Encrypt a server''s data"}}, {"id": "d", "text": {"en": "Improve a server''s security"}}]', 'a', null, 23),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "The small lock icon next to a website''s name in your browser indicates:"}', '[{"id": "a", "text": {"en": "The site is slow"}}, {"id": "b", "text": {"en": "The connection to the site is encrypted (HTTPS)"}}, {"id": "c", "text": {"en": "The site is a paid service"}}, {"id": "d", "text": {"en": "The site contains a virus"}}]', 'b', null, 24),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Which best demonstrates \"defense in depth\" in practice for an individual user?"}', '[{"id": "a", "text": {"en": "Combining a strong password, 2FA, and awareness of phishing red flags"}}, {"id": "b", "text": {"en": "Relying on a strong password alone"}}, {"id": "c", "text": {"en": "Using the same password everywhere for convenience"}}, {"id": "d", "text": {"en": "Ignoring software updates"}}]', 'a', null, 25),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "The internet is generally divided into two main types, known as:"}', '[{"id": "a", "text": {"en": "Fast internet and slow internet"}}, {"id": "b", "text": {"en": "Local internet and global internet"}}, {"id": "c", "text": {"en": "White internet and dark internet"}}, {"id": "d", "text": {"en": "Free internet and paid internet"}}]', 'c', null, 26),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "During incident response, which phase comes immediately after containment?"}', '[{"id": "a", "text": {"en": "Identification"}}, {"id": "b", "text": {"en": "Lessons learned"}}, {"id": "c", "text": {"en": "Eradication"}}, {"id": "d", "text": {"en": "Recovery"}}]', 'c', null, 27),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "What does a \"zero-day\" vulnerability refer to?"}', '[{"id": "a", "text": {"en": "Vulnerabilities that are old and already patched"}}, {"id": "b", "text": {"en": "Hardware-only vulnerabilities"}}, {"id": "c", "text": {"en": "Vulnerabilities not yet discovered by developers"}}, {"id": "d", "text": {"en": "Vulnerabilities that don''t actually exist"}}]', 'c', null, 28),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "The best security practice for IoT devices at home is to:"}', '[{"id": "a", "text": {"en": "Put them all on the same network as your main devices like your laptop"}}, {"id": "b", "text": {"en": "Buy the cheapest devices with no regard for security"}}, {"id": "c", "text": {"en": "Where possible, keep them on a separate wifi network from your main devices"}}, {"id": "d", "text": {"en": "Never connect them to the internet at all"}}]', 'c', null, 29),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Which of the following best describes a \"prepared statement\" in database security?"}', '[{"id": "a", "text": {"en": "Directly inserting raw user input into a SQL query"}}, {"id": "b", "text": {"en": "Removing the database entirely"}}, {"id": "c", "text": {"en": "Disabling the login page"}}, {"id": "d", "text": {"en": "Structuring a database query so user input is always treated as data, not executable code"}}]', 'd', null, 30),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Defense in depth means:"}', '[{"id": "a", "text": {"en": "Relying on one extremely strong layer of protection"}}, {"id": "b", "text": {"en": "Not needing any protection at all"}}, {"id": "c", "text": {"en": "Using multiple different layers of protection, so if one fails, others still hold"}}, {"id": "d", "text": {"en": "Using just one strong password"}}]', 'c', null, 31),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Malware that disguises itself as a useful app while hiding malicious code is called:"}', '[{"id": "a", "text": {"en": "Worm"}}, {"id": "b", "text": {"en": "Adware"}}, {"id": "c", "text": {"en": "Firewall"}}, {"id": "d", "text": {"en": "Trojan"}}]', 'd', null, 32),
  ('final_exam', null, null, '7a2fdc4c-3404-449e-b4a3-c21baef3c034', '{"en": "Social engineering primarily relies on exploiting:"}', '[{"id": "a", "text": {"en": "Weaknesses in human behavior and trust"}}, {"id": "b", "text": {"en": "Software vulnerabilities"}}, {"id": "c", "text": {"en": "Network weaknesses"}}, {"id": "d", "text": {"en": "Hardware strength"}}]', 'a', null, 33);
